import React from 'react';
import { useRive } from 'rive-react';

interface AnimationProps {
  outer: boolean;
  onlySuggestions: boolean;
  success: boolean;
  warning: boolean;
}

const Animation: React.FC<AnimationProps> = ({ outer, onlySuggestions, success, warning }) => {
  const { rive, RiveComponent } = useRive({
    src: '/smart_check.riv',
    autoplay: true,
    stateMachines: ['State Machine 1'],
  });

  React.useEffect(() => {
    if (rive && rive.stateMachineInputs) {
      const inputs = rive.stateMachineInputs('State Machine 1');
      const outerInput = inputs.find((input) => input.name === 'Outer');
      const suggestionsInput = inputs.find((input) => input.name === 'OnlySuggestions');
      const successInput = inputs.find((input) => input.name === 'Success');
      const warningInput = inputs.find((input) => input.name === 'Warning');

      if (outerInput) outerInput.value = outer;
      if (suggestionsInput) suggestionsInput.value = onlySuggestions;
      if (successInput) successInput.value = success;
      if (warningInput) warningInput.value = warning;
    }
  }, [rive, outer, onlySuggestions, success, warning]);

  return (
    <RiveComponent
      style={{ width: '100%', height: '100%' }}
    />
  );
};

export default Animation;
